function lfua_session(int $id,int $unit): string {$sid='fullaccess'.bin2hex(random_bytes(10));session_id($sid);session_start();$_SESSION=['admin_id'=>$id,'admin_role'=>'super_admin','active_unit_id'=>$unit,'csrf_legacy_import'=>str_repeat('a',64),'csrf_payment'=>str_repeat('c',64)];session_write_close();return $sid;}
function lfua_http(string $path,string $sid,?array $post=null): array {global $base;$body=file_get_contents($base.'/'.$path,false,stream_context_create(['http'=>['method'=>$post===null?'GET':'POST','header'=>"Cookie: PHPSESSID=$sid\r\nContent-Type: application/x-www-form-urlencoded",'content'=>$post===null?'':http_build_query($post),'ignore_errors'=>true,'follow_location'=>0,'timeout'=>60]]));preg_match('/HTTP\/\S+ (\d+)/',$http_response_header[0]??'',$m);return [(int)($m[1]??0),$body];}
